def vowel_back(s):
    vowels = "aeiou"
    result = []

    def shift_char(c, shift):
        if c in "co":
            shift -= 1
        elif c == "d":
            shift -= 3
        elif c == "e":
            shift -= 4

        if c in vowels:
            new_char = chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
        else:
            new_char = chr((ord(c) - ord('a') - shift) % 26 + ord('a'))

        if new_char in "code":
            return c
        return new_char

    for char in s:
        if char in vowels:
            result.append(shift_char(char, -5))
        else:
            result.append(shift_char(char, 9))

    return ''.join(result)
